package db

import (
	"context"
	"fmt"

	"github.com/jackc/pgx/v5/pgtype"
)

// EventWithPermalink holds an event row joined with its current route and owner handle.
// Added manually - not generated by sqlc.
type EventWithPermalink struct {
	EventID    int32            `json:"event_id"`
	EventType  string           `json:"event_type"`
	UserID     int32            `json:"user_id"`
	EntityType pgtype.Text      `json:"entity_type"`
	EntityID   pgtype.Int4      `json:"entity_id"`
	EndDate    pgtype.Timestamp `json:"end_date"`
	EventData  []byte           `json:"event_data"`
	IsDeleted  bool             `json:"is_deleted"`
	CreatedAt  pgtype.Timestamp `json:"created_at"`
	UpdatedAt  pgtype.Timestamp `json:"updated_at"`
	Txhash     string           `json:"txhash"`
	// Route fields - NULL when no current route exists.
	Slug       pgtype.Text      `json:"slug"`
	Handle     pgtype.Text      `json:"handle"`
	// Permalink is derived as "/handle/contest/slug"; empty when missing.
	Permalink  string           `json:"permalink"`
}

const getEventByIDQuery = `
SELECT
  e.event_id, e.event_type, e.user_id, e.entity_type, e.entity_id,
  e.end_date, e.event_data, e.is_deleted, e.created_at, e.updated_at, e.txhash,
  er.slug, u.handle_lc
FROM events e
LEFT JOIN event_routes er ON er.event_id = e.event_id AND er.is_current = true
LEFT JOIN users u ON u.user_id = e.user_id AND u.is_current = true
WHERE e.event_id = $1
  AND e.is_deleted = false
LIMIT 1
`

// GetEventByID returns an event row by ID, with permalink fields populated.
func (q *Queries) GetEventByID(ctx context.Context, eventID int64) (EventWithPermalink, error) {
	row := q.db.QueryRow(ctx, getEventByIDQuery, eventID)
	return scanEventRow(row)
}

const getEventBySlugQuery = `
SELECT
  e.event_id, e.event_type, e.user_id, e.entity_type, e.entity_id,
  e.end_date, e.event_data, e.is_deleted, e.created_at, e.updated_at, e.txhash,
  er.slug, u.handle_lc
FROM events e
JOIN event_routes er ON er.event_id = e.event_id
JOIN users u ON u.user_id = e.user_id AND u.is_current = true
WHERE u.handle_lc = lower($1)
  AND er.slug = $2
  AND e.is_deleted = false
ORDER BY er.is_current DESC
LIMIT 1
`

// GetEventBySlug looks up an event by owner handle and route slug.
func (q *Queries) GetEventBySlug(ctx context.Context, handle, slug string) (EventWithPermalink, error) {
	row := q.db.QueryRow(ctx, getEventBySlugQuery, handle, slug)
	return scanEventRow(row)
}

const listEventsQuery = `
SELECT
  e.event_id, e.event_type, e.user_id, e.entity_type, e.entity_id,
  e.end_date, e.event_data, e.is_deleted, e.created_at, e.updated_at, e.txhash,
  er.slug, u.handle_lc
FROM events e
LEFT JOIN event_routes er ON er.event_id = e.event_id AND er.is_current = true
LEFT JOIN users u ON u.user_id = e.user_id AND u.is_current = true
WHERE e.is_deleted = false
ORDER BY e.created_at DESC
LIMIT $1 OFFSET $2
`

// ListEventsParams holds pagination arguments for ListEvents.
type ListEventsParams struct {
	Limit  int32 `json:"limit"`
	Offset int32 `json:"offset"`
}

// ListEvents returns a paginated list of active events, newest first.
func (q *Queries) ListEvents(ctx context.Context, arg ListEventsParams) ([]EventWithPermalink, error) {
	rows, err := q.db.Query(ctx, listEventsQuery, arg.Limit, arg.Offset)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var events []EventWithPermalink
	for rows.Next() {
		var ev EventWithPermalink
		var slug pgtype.Text
		var handle pgtype.Text
		err := rows.Scan(
			&ev.EventID, &ev.EventType, &ev.UserID, &ev.EntityType, &ev.EntityID,
			&ev.EndDate, &ev.EventData, &ev.IsDeleted, &ev.CreatedAt, &ev.UpdatedAt, &ev.Txhash,
			&slug, &handle,
		)
		if err != nil {
			return nil, err
		}
		ev.Slug = slug
		ev.Handle = handle
		ev.Permalink = buildPermalink(handle, slug)
		events = append(events, ev)
	}
	return events, rows.Err()
}

// scannable is the minimal interface satisfied by pgx.Row.
type scannable interface {
	Scan(dest ...any) error
}

// scanEventRow scans a single event row from GetEventByID or GetEventBySlug.
func scanEventRow(row scannable) (EventWithPermalink, error) {
	var ev EventWithPermalink
	var slug pgtype.Text
	var handle pgtype.Text
	err := row.Scan(
		&ev.EventID, &ev.EventType, &ev.UserID, &ev.EntityType, &ev.EntityID,
		&ev.EndDate, &ev.EventData, &ev.IsDeleted, &ev.CreatedAt, &ev.UpdatedAt, &ev.Txhash,
		&slug, &handle,
	)
	if err != nil {
		return ev, err
	}
	ev.Slug = slug
	ev.Handle = handle
	ev.Permalink = buildPermalink(handle, slug)
	return ev, nil
}

// buildPermalink constructs "/handle/contest/slug" from nullable fields.
func buildPermalink(handle, slug pgtype.Text) string {
	if !handle.Valid || handle.String == "" || !slug.Valid || slug.String == "" {
		return ""
	}
	return fmt.Sprintf("/%s/contest/%s", handle.String, slug.String)
}